+static bool fuse_dev_all_closing(struct fuse_chan *fch)
+{
+	struct fuse_dev *pos;
+
+	lockdep_assert_held(&fch->lock);
+
+	list_for_each_entry(pos, &fch->devices, entry) {
+		if (!pos->closing)
